common = {
    "project": "This repository is a three-service Flask demonstration: idp_server.py (IDP, port 5003), resource_server.py (protected API, port 5004), and client_app.py (web client, port 5005).",
    "implemented": "Implemented here: SQLite users/clients/authorization codes/refresh tokens, Werkzeug password hashing, OAuth 2.0 Authorization Code flow, OIDC discovery and UserInfo, RS256 JWTs, JWKS verification, scopes, refresh, client sessions, and protected documents.",
    "workflow": "User -> client -> IDP -> token or code -> client -> protected API -> token validation -> scope check -> response.",
    "production": "Production improvement: move secrets and keys to a secret manager, use HTTPS, tighten cookie settings and CORS, validate redirect URIs strictly, add rate limiting and audit logs, and use a mature IAM product or hardened service design.",
}

raw = [
 (1, "Analyze the Entire Project First", "Documentation must follow source code, not assumptions.", "The repository contains three Flask services, four HTML templates, two SQLite databases, RSA key files, a runner, and an end-to-end test. The analysis found real OAuth/OIDC, JWT, refresh-token, scope, and session behavior; unimplemented items are called out as recommendations.", "Read source -> list routes -> inspect database schema -> trace requests -> separate implemented behavior from production advice."),
 (2, "Project Overview", "An IDP centralizes login and issues proof that other services can trust.", "The browser starts at the client on port 5005. The client sends the user to the IDP on port 5003; the IDP authenticates the user and issues tokens; the resource server on port 5004 protects profiles and documents.", "User -> Client -> IDP login -> authorization code -> client token exchange -> Resource API."),
 (3, "What Is an Identity Provider?", "An IDP answers: who is this person?", "Identity is the user record; authentication proves the user; authorization decides what the user may do. In the building analogy, the IDP is the security gate, the token is an entry pass, and the resource API is a restricted room.", "Credentials -> identity check -> signed pass -> API checks pass and permission."),
 (4, "Why Do We Need an IDP?", "Without an IDP every application repeats login and password storage.", "This project demonstrates one login authority serving a client and a separate API. Centralization enables consistent password handling, token issuance, SSO-style redirects, and shared policy, although a production IDP needs stronger operational controls.", "Many app logins -> one IDP -> reusable, audience-specific tokens."),
 (5, "Complete IDP Architecture", "The architecture separates identity, user experience, and business data.", "The IDP owns users and token signing. The client owns browser pages and its Flask session. The resource server owns private documents and verifies tokens with the IDP public key rather than receiving the private key.", "Browser -> client:5005 -> IDP:5003; client -> resource:5004; resource -> IDP JWKS when its key cache expires."),
 (6, "Technology Stack", "Each component has a small, clear responsibility.", "Python and Flask provide HTTP services; SQLite stores identity and documents; PyJWT creates and reads JWTs; cryptography handles RSA keys; Werkzeug hashes passwords; requests connects services; Flask-CORS allows cross-origin API calls; HTML templates render the UI.", "Browser HTTP -> Flask route -> Python logic -> SQLite or service-to-service request."),
 (7, "Complete User Authentication Flow", "Login is a chain of verifiable steps, not one magic action.", "The normal UI path is OAuth Authorization Code: the client creates state, the IDP checks credentials, the IDP stores a one-time code, the client exchanges it, and the API later verifies the access token.", "Login click -> state -> /authorize -> password check -> code -> /token -> access/id/refresh tokens -> API call."),
 (8, "User Registration Flow", "Registration creates an identity record after basic validation.", "POST /register accepts JSON or form data with username, email, password, and optional full_name. It rejects missing fields, passwords under six characters, and duplicate username/email values, then stores a salted Werkzeug hash.", "Form -> POST /register -> validate -> duplicate check -> hash -> INSERT users -> 201 response."),
 (9, "Password Security", "The database stores a password hash, never the original password.", "idp_server.py uses generate_password_hash during registration and check_password_hash during login. The algorithm is delegated to Werkzeug; the code never needs to reverse the hash.", "Password -> salted one-way hash -> database; entered password -> verifier -> match or reject."),
 (10, "Login Flow", "Login proves a known user controls the password.", "The direct endpoint POST /login looks up username, verifies the stored hash, and returns a short-lived RS256 access token plus a refresh token. The UI normally uses /authorize instead, so the client never receives the user's password.", "Credentials -> user lookup -> hash verification -> token creation -> JSON response or 401."),
 (11, "Login API Documentation", "An API contract tells callers exactly what to send and expect.", "POST /login accepts username and password as JSON or form data. Success returns access_token, token_type, expires_in, refresh_token, and user profile fields; missing fields return 400 and bad credentials return 401.", "POST /login {username,password} -> idp_server.login() -> create_access_token/create_refresh_token -> 200 JSON."),
 (12, "Token Explanation", "A token is a portable, time-limited statement issued by a trusted authority.", "The IDP creates access tokens; the client stores them in its Flask session; the client sends the access token as Authorization: Bearer to the resource server; the resource server verifies it.", "Login -> IDP signs token -> client session -> Bearer header -> API verifies."),
 (13, "JWT Explanation", "JWT is a signed data format: HEADER.PAYLOAD.SIGNATURE.", "This project uses RS256 and key id idp-key-1. Access-token claims include iss, sub, aud, iat, exp, user_id, email, name, and scope. JWT payloads are readable; the signature protects integrity but does not encrypt the contents.", "Header names algorithm/key -> payload carries claims -> signature proves IDP signed the exact bytes."),
 (14, "JWT Creation Flow", "The IDP signs a token only after authentication succeeds.", "create_access_token builds claims with a 15-minute lifetime and audience resource_server, then PyJWT signs the token with the RSA private key. create_id_token creates the OIDC identity token for the client audience.", "Verified user -> claims -> RS256 private-key signature -> token returned."),
 (15, "JWT Validation Flow", "The API trusts a token only after several checks pass.", "require_token parses Bearer syntax, reads kid/alg, loads the matching public key from JWKS, verifies RS256 signature, issuer, audience, and expiration, then checks the required scope.", "Header -> kid -> JWKS public key -> signature/iss/aud/exp -> scope -> request.current_user."),
 (16, "Cookies vs Local Storage vs Memory", "Where authentication state is stored changes the attack surface.", "This client uses Flask's session cookie mechanism to hold access_token, refresh_token, id_token, and user data. The code does not use localStorage or sessionStorage. The current app generates a random SECRET_KEY at startup, so sessions are invalidated on restart; production should use a stable secret and secure cookie flags.", "OAuth callback -> server session values -> browser cookie -> client reads session on later requests."),
 (17, "Authentication vs Authorization", "Authentication asks who you are; authorization asks what you may do.", "The IDP authenticates Alice by verifying her password. The resource server authorizes her request by checking scopes such as profile, read, or write.", "Password proof -> identity -> token -> scope check -> allowed or forbidden."),
 (18, "Roles", "A role is a named bundle of permissions.", "No roles table or role-checking middleware exists in this project. Access is scope-based, so a role model is a production recommendation rather than an implemented feature.", "Future: user -> role -> permissions -> claims/policy -> endpoint."),
 (19, "Permissions", "Permissions are the small actions an API allows.", "The implemented permission-like values are OAuth scopes: openid, profile, email, read, and write. resource_server.py checks profile on /api/profile, read on GET /api/data, and write on POST /api/data.", "Scope claim -> required_scope -> 200 or 403 insufficient_scope."),
 (20, "Protected Route Flow", "A protected route rejects requests before business logic runs.", "GET /api/profile is decorated with require_token(required_scope='profile'). Once verified, it returns identity data from the token claims. GET and POST /api/data use read and write scopes and query or update SQLite documents.", "Request -> middleware -> token claims -> scope -> handler -> response."),
 (21, "Complete API Documentation", "The project exposes public, identity, client, and protected-resource endpoints.", "IDP: /, /.well-known/openid-configuration, /jwks, /register, /login, /token/refresh, /authorize, /token, /userinfo. Resource: /, /api/health, /api/profile, /api/data GET/POST. Client: /, /login, /callback, /profile, /data GET/POST, /refresh-token, /logout.", "Route -> validation/middleware -> database or remote service -> JSON, HTML, redirect, or error."),
 (22, "Authentication API Categories", "Grouping endpoints makes a large API easier to learn.", "Registration is /register; direct login is /login; OAuth login is /authorize plus /token; refresh is /token/refresh or /token with grant_type refresh_token; identity is /userinfo; protected resources are /api/profile and /api/data. Password reset, role management, and permission management are not implemented.", "Choose category -> call endpoint -> receive identity/token/resource result."),
 (23, "Logout Flow", "Logout in this demo clears the client session.", "GET /logout calls session.clear() in client_app.py and redirects home. It does not revoke refresh tokens in the IDP or invalidate already-issued JWTs; a still-valid token may work until expiry.", "Logout click -> local session cleared -> home; production -> revoke tokens and/or end IDP session."),
 (24, "Refresh Token Flow", "Refresh tokens let the client obtain a new access token without asking for the password again.", "The IDP stores opaque refresh tokens in SQLite with username, client_id, scope, expiry, and revoked flag. The client retries a 401 once by posting grant_type=refresh_token to /token; access tokens last 15 minutes and refresh tokens seven days.", "Expired access token -> refresh token -> IDP lookup/expiry/revocation check -> new access token -> retry."),
 (25, "Session-Based Authentication", "A session links a browser to server-side application state.", "The client uses Flask sessions to remember OAuth tokens and profile data between requests. The IDP and resource server do not use login sessions for API authorization; they use tokens.", "Browser cookie -> client Flask session -> token added to outbound API request."),
 (26, "OAuth 2.0", "OAuth 2.0 lets a client obtain limited access without handling the user's password.", "This project implements the Authorization Code flow: /authorize authenticates and creates a code, /token exchanges the one-time code for tokens, and the resource server accepts the access token.", "Client redirect -> user authenticates at IDP -> code -> back-channel token exchange -> API."),
 (27, "OpenID Connect", "OIDC adds identity information on top of OAuth 2.0.", "The project implements OIDC discovery, an id_token from the code exchange, and /userinfo. OAuth supplies authorization to the resource server; OIDC supplies standardized identity claims to the client.", "OIDC discovery -> authorization code -> id_token/access_token -> /userinfo."),
 (28, "ID Token vs Access Token", "These tokens have different audiences and jobs.", "The id_token is created for client_app_demo and describes the authenticated user. The access token is created for audience resource_server and is sent to protected APIs. The API must not use an ID token as an API credential.", "ID token -> client identity; access token -> resource API authorization."),
 (29, "Complete Request to Response Flow", "Every operation can be followed from user action to response.", "A login button triggers a redirect; an authorization form triggers credential verification; a callback exchanges a code; a profile page calls the API; middleware validates the JWT; the API returns claims.", "Frontend event -> HTTP request -> Flask route -> helper/database -> response -> next request."),
 (30, "Error Handling", "Errors tell the caller whether to fix input, authenticate, or change permissions.", "The code uses 400 for malformed requests, 401 for missing/invalid credentials or tokens, 403 for missing scopes, 404 for missing users, 409 for duplicate registration, and 201/200 for successful writes/reads. Database and network failures are logged but not consistently mapped to a production error model.", "Failure -> status code + JSON/HTML message -> client redirect, retry, or display."),
 (31, "Security Analysis", "The project demonstrates important controls but is educational, not production-ready.", "Implemented: password hashing, RS256 signatures, issuer/audience/expiry checks, state checking, one-time authorization codes, refresh expiry/revocation fields, parameterized SQLite queries, and scopes. Gaps: HTTP URLs, permissive CORS, hard-coded client secret, key files in the repo, no rate limiting, no MFA, no audit log, and no strict redirect validation at the token endpoint.", "Control -> threat reduced; missing control -> production work item."),
 (32, "Environment Variables", "Configuration should be separated from source code.", "The resource and client services read IDP_BASE_URL and the client reads RESOURCE_SERVER_URL. The IDP issuer, client ID/secret, redirect URI, lifetimes, and paths are code constants; secrets should move to environment variables or a secret manager.", "Environment/config -> service startup -> routes use trusted values."),
 (33, "Database Architecture", "The identity database stores identity protocol state; the resource database stores business data.", "idp_database.db has users, clients, auth_codes, and refresh_tokens. resource_database.db has user_documents. There are no roles, permissions, sessions, audit_logs, or separate credentials tables.", "users -> codes/tokens; token subject -> user_documents.username."),
 (34, "Database Flow", "Database writes and reads are tied to authentication stages.", "Registration inserts a hashed user. Login reads the user and creates a refresh-token row. Authorization inserts a one-time code. Token exchange marks that code used and creates tokens. Resource access reads or inserts documents for the token subject.", "Validate -> parameterized SQL -> commit -> JSON/HTML result."),
 (35, "IDP vs Application", "The IDP proves identity; the application delivers business features.", "Here the IDP owns login, users, codes, keys, and tokens. The client owns pages and session handling. The resource server owns document data and business authorization based on scopes.", "IDP issues proof -> application presents proof -> resource server serves business data."),
 (36, "Single Sign-On", "SSO means one IDP login can serve multiple client applications.", "The current demo has one registered client, but its authorization-code design is the foundation for SSO. Additional clients would need registered IDs, validated redirect URIs, and an IDP browser session to avoid repeated login.", "App A -> IDP session -> App B/App C receive their own audience-specific tokens."),
 (37, "Real-World IDP Architecture", "Production identity platforms separate edge, identity, keys, sessions, policy, and observability.", "This demo compresses those responsibilities into one Flask IDP process and SQLite. A production system commonly adds an API gateway, durable database, key rotation/JWKS publishing, session and token services, audit logs, MFA, and monitoring.", "Clients -> gateway -> identity services -> databases/keys/events."),
 (38, "Scaling the Simple IDP", "Scaling means removing single-process and single-file bottlenecks.", "At small scale this local SQLite design is easy to understand. At higher scale use a managed relational database, indexes, multiple stateless service instances, shared session/refresh infrastructure, cache, key rotation, rate limiting, and telemetry.", "One process -> replicated services -> shared durable state -> monitored capacity."),
 (39, "Production IDP Components", "Each production component addresses a failure or security concern.", "Useful additions include a load balancer, gateway, identity/token services, Redis for short-lived state, a durable database, audit logging, monitoring, rate limiter, secret manager, KMS/HSM, notifications, and MFA service.", "Request -> edge controls -> identity policy -> durable state -> signed result -> audit event."),
 (40, "MFA", "Multi-factor authentication combines different kinds of proof.", "MFA is not implemented. A production flow could require password plus authenticator-app OTP, WebAuthn/passkey, or a carefully evaluated notification factor; SMS/email should be treated as weaker recovery channels.", "Password -> second factor -> authentication success -> token."),
 (41, "Password Reset", "Password reset must prove control of a recovery channel without exposing the old password.", "Reset is not implemented. A safe future flow creates a short-lived, single-use, hashed reset token, sends a link, verifies it, updates the password hash, expires sessions/tokens, and records the event.", "Forgot password -> generic response -> one-time email link -> new hash -> revoke old auth state."),
 (42, "Audit Logging", "Audit logs answer who did what, when, and from where.", "No audit-log table or event pipeline is implemented. Production should record successful and failed logins, logout, refresh, password changes, role changes, token revocation, and administrative actions without storing secrets.", "Security event -> structured log -> protected retention/search -> alert or investigation."),
 (43, "Rate Limiting", "Authentication endpoints are attractive targets for brute-force attacks.", "No rate limiter or account lockout is implemented. Production should throttle by account and network signals, add monitoring and progressive delays, and consider CAPTCHA only where appropriate.", "Repeated attempts -> limiter -> delay/block/challenge -> alert."),
 (44, "Debugging Guide", "Debug from the outside inward, following one request at a time.", "For login, check redirect URL, state, form fields, IDP logs, user row, password verifier, and token response. For 401, check the Bearer header, kid/alg, JWKS, issuer, audience, expiry, and refresh path. For 403, inspect the required scope.", "Browser -> client log -> IDP log -> resource log -> response status."),
 (45, "Testing", "Tests turn an authentication flow into repeatable evidence.", "test_flow.py exercises discovery, JWKS, registration, direct login, refresh, authorization code, replay prevention, UserInfo, protected profile/data, missing token, and tampered-token rejection. Password reset, MFA, role policy, and logout revocation tests are absent because those features are absent.", "Start services -> run test_flow.py -> assert status, claims, and security behavior."),
 (46, "Complete End-to-End Example", "The most important story is login followed by a protected API request.", "The browser uses client_app.login, the IDP's authorize route verifies credentials and creates a code, client_app.callback calls /token, and client_app.profile calls resource /api/profile. The resource middleware validates the token and scope before returning the profile.", "Click login -> /authorize -> code -> /callback -> /token -> session -> /api/profile -> 200."),
 (47, "Mermaid Diagrams", "Diagrams make request ownership and trust boundaries visible.", "The guide includes text workflows suitable for Mermaid: architecture, registration, login, token creation/validation, protected API, logout, SSO, database relationships, and production architecture. Every diagram should keep the three ports and trust boundaries explicit.", "Sequence participants -> request arrows -> validation -> response arrows."),
 (48, "Folder Structure", "Files are organized by service and responsibility.", "Top-level Python files are the three services plus key generation, runner, and tests. templates contains home, login, profile, and data pages. Two SQLite files hold separate domains; PEM files hold signing material.", "Service file -> route/helper -> template or database."),
 (49, "File-by-File Explanation", "A useful code reading method connects each file to its caller and security responsibility.", "idp_server.py owns identity protocol logic; resource_server.py owns JWKS validation and documents; client_app.py owns redirects, sessions, and API calls; generate_keys.py creates RSA keys; run_all.py starts processes; test_flow.py verifies behavior; templates render user-facing pages.", "Entry point -> route -> helper -> external dependency -> output."),
 (50, "IDP Glossary", "A glossary gives beginners a stable vocabulary.", "Identity means account information; authentication means proving identity; authorization means permission; access token means API credential; refresh token means token-renewal credential; JWT means signed claims format; OAuth means delegated authorization; OIDC means identity on OAuth; RBAC means role-based access control.", "Learn term -> map it to a route/claim/table -> use it in explanations."),
 (51, "Common Beginner Confusions", "Similar-sounding security terms solve different problems.", "JWT is a format, not authentication by itself. JWTs are signed rather than encrypted here. OAuth is not JWT; OIDC is not identical to OAuth; an IDP is a service, not merely a database; logout clears this client session but does not revoke JWTs.", "Question -> identify protocol/data format/storage -> explain its exact project role."),
 (52, "Kafka / Microservices Integration", "Events can notify other services without coupling them to login requests.", "Kafka is not present. A future user-created event could feed notification, analytics, or provisioning services, but identity creation should succeed or fail independently from noncritical consumers.", "Registration -> committed user -> event -> consumers -> retries/dead-letter handling."),
 (53, "IDP vs Custom Login", "Custom login is one application feature; an IDP is a reusable trust service.", "This repository is a learning implementation of an IDP, not a replacement for hardened products in high-risk production. Dedicated IAM is valuable when many apps, SSO, federation, MFA, lifecycle, compliance, or delegated access are required.", "Single app need -> local auth; many apps/security requirements -> shared IDP."),
 (54, "Interview Questions", "Interview preparation is strongest when answers trace this code.", "Prepare beginner, intermediate, and advanced questions around routes, password hashing, RS256/JWKS, code replay, scopes, sessions, refresh, OAuth/OIDC, 401 vs 403, key rotation, scaling, and missing controls. The generated topic file contains a compact question bank prompt and project anchors.", "Question -> identify exact file/function -> explain tradeoff -> name production improvement."),
 (55, "Two-Minute Project Explanation", "A short explanation should name the trust boundaries and main flow.", "Say: this is a Flask IDP ecosystem with a client and resource server. The client redirects to the IDP, receives an authorization code, exchanges it for tokens, stores them in a session, and calls the API with a Bearer JWT. The API verifies RS256 using JWKS and enforces scopes.", "Problem -> architecture -> login -> token -> protected API -> security caveat."),
 (56, "Five-Minute Technical Explanation", "A deeper explanation adds claims, databases, errors, and tradeoffs.", "Walk through browser, client state, IDP users and codes, RSA signing, token lifetimes, callback exchange, JWKS cache, issuer/audience checks, scope enforcement, SQLite documents, refresh, logout, and production gaps.", "User -> client -> IDP -> authN -> code/tokens -> API authN -> authZ -> resource."),
 (57, "Learning Path", "Learn the system from transport to production policy.", "Level 1 is HTTP/APIs; then authentication; password hashing; JWT and sessions; scopes/RBAC; OAuth; OIDC; SSO; MFA; and production IAM. Each level should be practiced against a route, claim, or test in this repository.", "Concept -> small experiment -> observe request/response -> add security reasoning."),
 (58, "Documentation Files", "Documentation should be modular enough to read one concept at a time.", "This deliverable creates docs/topics/01 through 64 as individual Markdown pages, plus a master Markdown document and a complete PDF. The project README is updated with links so the guide is discoverable.", "Topic file -> master index -> PDF page -> repository README link."),
 (59, "Master Markdown Document", "The master guide is the single searchable source of truth.", "COMPLETE_IDP_DOCUMENTATION.md combines all 64 topic pages, a project facts summary, endpoint inventory, architecture, workflows, security analysis, glossary, interview guidance, and final flow. It preserves the distinction between implemented features and recommendations.", "Repository evidence -> topic pages -> consolidated guide."),
 (60, "Complete PDF", "The PDF is a printable version with one numbered topic per page.", "COMPLETE_IDP_DOCUMENTATION.pdf includes a title page, contents page, project facts, readable workflows, endpoint examples, diagrams in text form, security notes, glossary, and interview guidance. Each of the 64 numbered topics starts on its own page.", "Markdown content -> styled report -> page breaks -> numbered PDF pages."),
 (61, "PDF Quality Check", "A document is not complete until its rendering is inspected.", "The generated PDF uses fixed margins, page breaks, readable fonts, page numbers, and compact tables. Validation checks page count, extracted topic headings, presence of page numbering, and rendered page images for clipping or overlap.", "Generate -> render PNGs -> inspect representative pages -> extract text -> final check."),
 (62, "Final Master Flow", "The complete flow joins browser, IDP, tokens, API checks, and resource output.", "The browser reaches the client, the client starts login, the IDP authenticates and consults SQLite, signs a token, and the client calls the resource API. The resource server validates signature, issuer, audience, expiry, and scope before returning documents.", "User -> client -> login -> IDP -> authN/database -> token -> API -> authN -> authZ -> resource."),
 (63, "Most Important Question", "A confident answer traces what, why, where, input, output, failure, and production handling.", "For this project: username/password enter the IDP authorization form; idp_server.authorize checks the user and stores a code; client_app.callback exchanges it at /token; the client stores tokens in session; resource_server.require_token validates the access token; the endpoint applies a scope and returns the resource.", "Input -> route -> helper -> storage/crypto -> output; failures become 400/401/403/409 or redirect messages."),
 (64, "Accuracy Rules", "The documentation must never turn a recommendation into a fact.", "This guide is grounded in the inspected files and live SQLite schemas. It explicitly says that roles, password reset, MFA, audit logging, rate limiting, and Kafka are not implemented, and it avoids reproducing secret values or real token strings.", "Inspect source -> verify behavior -> document exact file/function -> label gaps -> protect secrets."),
]

def esc(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def topic_md(n, title, meaning, detail, flow):
    return f"""# Topic {n}: {title}\n\n## In simple words\n\n{meaning}\n\n## What this project does\n\n{detail}\n\n## Workflow\n\n```text\n{flow}\n```\n\n## Project anchor\n\n{common['project']}\n\n## Implemented vs production\n\n{common['implemented']}\n\n{common['production']}\n"""

for n, title, meaning, detail, flow in raw:
    (TOPICS / f"{n:02d}-{title.lower().replace(' ', '-').replace('/', '-').replace('?', '').replace(':','')}.md").write_text(topic_md(n, title, meaning, detail, flow), encoding="utf-8")

facts = """## Project facts from source inspection\n\n- IDP: `idp_server.py`, Flask, port 5003.\n- Client: `client_app.py`, Flask, port 5005.\n- Resource server: `resource_server.py`, Flask, port 5004.\n- Storage: `idp_database.db` and `resource_database.db`, both SQLite.\n- Tokens: RS256 JWT access tokens, OIDC ID tokens, opaque refresh tokens.\n- Passwords: Werkzeug salted password hashes.\n- Authorization: OAuth scopes `profile`, `read`, and `write` (plus identity scopes).\n- Important missing production controls: MFA, rate limiting, audit logs, password reset, roles/permissions tables, HTTPS deployment, managed secrets, and key rotation.\n"""

master = "# Complete IDP Documentation\n\n## Beginner-friendly implementation guide\n\nThis guide explains the actual repository from beginner concepts through production IAM architecture. It contains 64 numbered topics because the supplied specification is numbered 1-64, although the request described it as 60.\n\n" + facts + "\n## Master flow\n\n```text\nUser -> Client :5005 -> IDP :5003 /authorize -> one-time code\nClient /callback -> IDP /token -> access token + ID token + refresh token\nClient session -> Resource API :5004 with Bearer access token\nResource middleware -> JWKS -> signature/issuer/audience/expiry -> scope\nResource SQLite -> protected profile/documents -> response\n```\n\n## Topic index\n\n" + "\n".join(f"{n}. [{title}](topics/{n:02d}-{title.lower().replace(' ', '-').replace('/', '-').replace('?', '').replace(':','')}.md)" for n, title, *_ in raw) + "\n\n---\n\n" + "\n\n---\n\n".join(f"{topic_md(n,title,meaning,detail,flow)}" for n,title,meaning,detail,flow in raw)
(DOCS / "COMPLETE_IDP_DOCUMENTATION.md").write_text(master, encoding="utf-8")

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="Cover", parent=styles["Title"], alignment=TA_CENTER, fontSize=24, leading=30, textColor=colors.HexColor("#12324a"), spaceAfter=18))
styles.add(ParagraphStyle(name="Sub", parent=styles["Normal"], alignment=TA_CENTER, fontSize=11, leading=16, textColor=colors.HexColor("#456")))
styles.add(ParagraphStyle(name="Topic", parent=styles["Heading1"], fontSize=18, leading=22, textColor=colors.HexColor("#12324a"), spaceAfter=12))
styles.add(ParagraphStyle(name="Small", parent=styles["Normal"], fontSize=9.5, leading=13, spaceAfter=7))
styles.add(ParagraphStyle(name="Flow", parent=styles["Code"], fontSize=8.5, leading=11, backColor=colors.HexColor("#eef4f7"), borderPadding=8, spaceBefore=4, spaceAfter=10))

pdf_path = DOCS / "COMPLETE_IDP_DOCUMENTATION.pdf"
doc = SimpleDocTemplate(str(pdf_path), pagesize=letter, rightMargin=0.62*inch, leftMargin=0.62*inch, topMargin=0.62*inch, bottomMargin=0.58*inch)
story = []
story += [Spacer(1, 1.0*inch), Paragraph("Complete IDP Documentation", styles["Cover"]), Paragraph("Beginner understanding -> actual implementation -> security -> production IAM", styles["Sub"]), Spacer(1, 0.35*inch), Paragraph("Source: inspected repository at C:/Users/itzme/Desktop/All Stacks/03-IDP", styles["Sub"]), Paragraph("The supplied prompt contains 64 numbered topics; this PDF preserves all 64.", styles["Sub"]), PageBreak()]
story += [Paragraph("Contents", styles["Topic"]), Paragraph("Each numbered topic begins on a new page.", styles["Small"])]
contents = [[str(n), title] for n, title, *_ in raw]
t = Table(contents, colWidths=[0.45*inch, 6.1*inch], repeatRows=1)
t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#dceaf1')),('GRID',(0,0),(-1,-1),0.25,colors.HexColor('#b5c7d0')),('FONTNAME',(0,0),(-1,-1),'Helvetica'),('FONTSIZE',(0,0),(-1,-1),8.3),('LEADING',(0,0),(-1,-1),10),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,0),(-1,-1),[colors.white, colors.HexColor('#f7fafb')])]))
story += [t, PageBreak()]
for n, title, meaning, detail, flow in raw:
    story += [Paragraph(f"Topic {n}: {esc(title)}", styles["Topic"]), Paragraph("In simple words", styles["Heading2"]), Paragraph(esc(meaning), styles["Small"]), Paragraph("What this project does", styles["Heading2"]), Paragraph(esc(detail), styles["Small"]), Paragraph("Workflow", styles["Heading2"]), Paragraph(esc(flow).replace("\n", "<br/>"), styles["Flow"]), Paragraph("Project anchor", styles["Heading2"]), Paragraph(esc(common["project"]), styles["Small"]), Paragraph("Implemented vs production", styles["Heading2"]), Paragraph(esc(common["implemented"]), styles["Small"]), Paragraph(esc(common["production"]), styles["Small"]), PageBreak()]

def footer(canvas, doc):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#c5d4dc'))
    canvas.line(0.62*inch, 0.42*inch, 7.88*inch, 0.42*inch)
    canvas.setFont('Helvetica', 8)
    canvas.setFillColor(colors.HexColor('#557'))
    canvas.drawString(0.62*inch, 0.25*inch, 'Custom Flask IDP documentation')
    canvas.drawRightString(7.88*inch, 0.25*inch, f'Page {doc.page}')
    canvas.restoreState()

doc.build(story, onFirstPage=footer, onLaterPages=footer)
print(f"Created {len(raw)} topic Markdown files, master Markdown, and {pdf_path}")
